use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-operation-census176";fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}fn pin(pins:&mut BTreeMap<String,String>,p:impl AsRef<Path>){pins.insert(p.as_ref().display().to_string(),hash(&p));}
fn link(){assert_eq!(load(r("native/result.json"))["status"],"complete");assert!(!r("link-plan.json").exists());let mut pins:BTreeMap<String,String>=serde_json::from_value(load(r("build-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}for(p,h)in load(r("frozen-candidate.json"))["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}
let sha=fs::read_dir(r("frozen/candidate")).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("libsha2-")&&p.extension().unwrap()=="rlib").collect::<Vec<_>>();assert_eq!(sha.len(),1);let steps=json!([{"kind":"link-sdk","name":"census","artifacts":r("frozen-candidate-cargo.jsonl"),"driver":r("driver.rs"),"additional_sources":[r("perf_support.rs")],"additional_rustc_flags":["--extern",format!("sha2={}",sha[0].display())],"timeout_seconds":600}]);for f in["campaign.rs","campaign","frozen-candidate.json","frozen-candidate-cargo.jsonl"]{pin(&mut pins,r(f));}save(r("link-pins.json"),&json!(pins));save(r("link-plan.json"),&json!({"version":1,"source_pins":r("link-pins.json"),"steps":steps}));println!("Prepared1native census link;extraSHA2 appended to native optimized defaults");}
fn prepare(){assert_eq!(load(r("consumers/result.json"))["status"],"complete");assert!(!r("capture-plan.json").exists());let mut pins:BTreeMap<String,String>=serde_json::from_value(load(r("link-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let command=load(r("consumers/census/command.json"));for f in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(command["argv"].as_array().unwrap().contains(&json!(f)),"missing{f}");}
let id=load(r("consumers/census/artifacts.json"));assert_eq!(hash(id["binary"].as_str().unwrap()),id["binary_sha256"]);pin(&mut pins,id["binary"].as_str().unwrap());for(p,h)in id["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}pin(&mut pins,r("consumers/census/command.json"));pin(&mut pins,r("consumers/census/artifacts.json"));let fixtures=load("/home/ubuntu/src/zopro-perf-work/late-m3-query176/fixtures.json");
let mut steps=Vec::new();let mut jobs=Vec::new();for shape in["1x2","2x2"]{let f=&fixtures[format!("{shape}-B")];let oracle=load(f["oracle"].as_str().unwrap());assert_eq!(hash(f["fixture"].as_str().unwrap()),oracle["fixture_sha256"]);for k in["fixture","oracle"]{pin(&mut pins,f[k].as_str().unwrap());}for on in[false,true]{for workers in[1usize,32]{let name=format!("{shape}-{}-w{workers}",if on{"ON"}else{"OFF"});let mut env=load(r("native-plan.json"))["steps"][0]["environment"].clone();for k in["RUSTFLAGS","CARGO_TARGET_DIR","CARGO_BUILD_JOBS"]{env.as_object_mut().unwrap().remove(k);}env["ZOPRO_CPU_LATE_M3"]=json!(if on{"1"}else{"0"});let cpus=if workers==1{"2"}else{"0-31"};steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c",cpus,id["binary"],"B",f["fixture"],f["oracle"],workers.to_string(),"1"],"environment":env,"timeout_seconds":600}));jobs.push(json!({"name":name,"shape":shape,"on_requested":on,"workers":workers,"fixture":f}));}}}
save(r("jobs.json"),&json!(jobs));pin(&mut pins,r("jobs.json"));save(r("capture-pins.json"),&json!(pins));save(r("capture-plan.json"),&json!({"version":1,"source_pins":r("capture-pins.json"),"steps":steps}));println!("Prepared8one-query diagnostic steps;no prime/clock/proof;allinputs independentcompleteMSMverified");}
fn finish(){assert_eq!(load(r("runs/result.json"))["status"],"complete");assert!(!r("analysis.json").exists());for(p,h)in load(r("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
let mut cases=BTreeMap::new();for j in load(r("jobs.json")).as_array().unwrap(){let name=j["name"].as_str().unwrap();let raw=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let lines=raw.lines().filter_map(|l|l.strip_prefix("CENSUS ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let v:Value=serde_json::from_str(lines[0]).unwrap();assert_eq!(v["workers"],j["workers"]);assert_eq!(v["point_inputs_unchanged"],true);assert_eq!(v["independent_complete_MSM_hash_matches"],true);assert_eq!(v["no_latency_measurement"],true);let candidate=j["shape"]=="1x2"&&j["on_requested"]==true;assert_eq!(v["candidate_used"],candidate);assert_eq!(v["metadata_route"],if candidate{313}else{0});assert_eq!(v["ordinary_windows"],if candidate{36}else{20});cases.insert(name.to_string(),v);}
for shape in["1x2","2x2"]{for mode in["OFF","ON"]{for key in["totals","global","normalized_projective_points"]{assert_eq!(cases[&format!("{shape}-{mode}-w1")][key],cases[&format!("{shape}-{mode}-w32")][key],"{shape}/{mode}/{key}");}}}
for workers in[1,32]{for key in["totals","global","normalized_projective_points"]{assert_eq!(cases[&format!("2x2-OFF-w{workers}")][key],cases[&format!("2x2-ON-w{workers}")][key]);}}
let a=json!({"complete":true,"cases":cases,"worker1_32_aggregate_counts_identical":true,"grouped2x2_OFF_ON_counts_identical":true,"new_independently_checked_complete_queries":8,"new_proofs":0,"proof_ledger":29461,"production_changed":false,"adopted":false,"no_performance_claim":true,"previous_goal_turn_classification":"PROGRESS"});save(r("analysis.json"),&a);println!("8completequerycensusesPASS;aggregatecounts1vs32 andgroupedbypassOFFONexact;no latency");}
